"""04 json-render · 2 DECLARATIVE — the model streams the spec itself, as JSONL patches.

New compared with 1-static:
  * The system prompt is generated by json-render from the catalog (catalog.prompt() in
    web/prompt.mjs -> web/prompt.txt). It teaches the model json-render's streaming format:
    one RFC 6902 JSON Patch per line, root first, state right after the elements using it.
  * Each finished line is forwarded to the page immediately; the page's
    createSpecStreamCompiler applies it and <Renderer> redraws: incremental rendering.
  * At the end the server compiles the lines with json-render and validates the spec against
    the catalog (Zod) and json-render's structural checks. On errors: reset + one retry.
  * The finished spec is also drawn by the Python terminal renderer (right-hand pane, and
    printed in the server's terminal): one spec, two targets.

Run:  python 04-json-render/2-declarative/server.py   then open http://localhost:8000
"""

import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path[:0] = [str(HERE.parents[1]), str(HERE.parent)]

from ag_ui.core import RunAgentInput  # noqa: E402

import jr_tools as jr  # noqa: E402
from shared.agui import create_app, custom, last_user_text, serve, stream_run, text_message  # noqa: E402

OFFLINE_REPLY = (HERE / "offline_reply.jsonl").read_text()
MAX_ATTEMPTS = 2

app = create_app(HERE, mounts={"/jr": HERE.parent / "web"})


@app.post("/agent")
def agent(run_input: RunAgentInput):
    def body():
        messages = [{"role": "system", "content": jr.PROMPT}, {"role": "user", "content": last_user_text(run_input)}]
        for attempt in range(1, MAX_ATTEMPTS + 1):
            yield jr.reset()
            jsonl = yield from jr.stream_patches(messages, OFFLINE_REPLY)
            result = jr.check(jsonl)
            yield custom("validation", {"attempt": attempt, "errors": result["errors"]})
            if not result["errors"]:
                print(jr.render_terminal(result["spec"]), flush=True)  # target 2: this terminal
                yield jr.terminal(result["spec"])
                yield from text_message(f"{result['patches']} patches, {len(result['spec']['elements'])} elements, valid against the catalog.")
                return
            messages += [
                {"role": "assistant", "content": jsonl},
                {"role": "user", "content": "json-render rejected the spec:\n- " + "\n- ".join(result["errors"]) + "\nStream the whole corrected spec again."},
            ]
        raise ValueError("no valid spec: " + "; ".join(result["errors"]))

    return stream_run(run_input, body)


if __name__ == "__main__":
    serve(app)
